css:
.rpos-inv { direction: rtl; font-family: "Noto Naskh Arabic", "Amiri", sans-serif; color: #14171a; }
.rpos-inv .en { font-family: "IBM Plex Sans", Arial, sans-serif; font-size: 0.82em; color: #6b7280; }
.rpos-inv .num { font-family: "IBM Plex Mono", monospace; direction: ltr; unicode-bidi: embed; }

.rpos-inv .head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #14171a; padding-bottom: 10px; }
.rpos-inv .title { font-size: 20px; font-weight: 700; line-height: 1.5; }
.rpos-inv .title .en { display: block; font-weight: 400; }
.rpos-inv .qr { width: 110px; height: 110px; }

.rpos-inv .parties { display: flex; gap: 18px; margin: 14px 0; }
.rpos-inv .party { flex: 1; border: 1px solid #d8dade; border-radius: 6px; padding: 10px 12px; }
.rpos-inv .cap { display: block; font-size: 11px; color: #6b7280; margin-bottom: 2px; }
.rpos-inv .nm { font-weight: 700; margin-bottom: 4px; }
.rpos-inv .addr { font-size: 12px; color: #4b5563; }

.rpos-inv table { width: 100%; border-collapse: collapse; }
.rpos-inv .meta td { padding: 4px 0; width: 50%; }
.rpos-inv .lines { margin-top: 12px; }
.rpos-inv .lines th, .rpos-inv .lines td { border: 1px solid #d8dade; padding: 6px 8px; font-size: 13px; }
.rpos-inv .lines th { background: #f3f1ed; font-weight: 700; }
.rpos-inv .lines .i { width: 30px; text-align: center; }
.rpos-inv .n { text-align: left; font-family: "IBM Plex Mono", monospace; direction: ltr; }

.rpos-inv .totals { margin: 12px 0 0 auto; width: 60%; }
.rpos-inv .totals td { padding: 5px 8px; border-bottom: 1px solid #eceef0; }
.rpos-inv .totals .grand td { font-weight: 700; font-size: 15px; border-top: 2px solid #14171a; border-bottom: none; }
.rpos-inv .pay td { color: #4b5563; font-size: 13px; }

.rpos-inv .note { margin-top: 12px; font-size: 12px; color: #4b5563; }
.rpos-inv .warn { margin-top: 14px; padding: 8px 10px; border: 1px solid #b91c1c; border-radius: 6px; color: #b91c1c; font-size: 12px; }
